  'ATT', 'ATT', 'ATT', 'ATT'
]

const SHIRT_NUMBERS = {
  GK: [1, 13, 25],
  DEF: [2, 3, 4, 5, 6, 15, 22],
  MID: [8, 10, 14, 16, 18, 20],
  ATT: [7, 9, 11, 17]
